  "editorialNotes": [
    {
      "title": "Everton confirma o bom momento.",
      "text": "Terceiro colocado na Geral, eliminou o Rolo Compressor por 193,95 a 174,09, avançou às quartas e assumiu o segundo maior patrimônio da liga, com C$ 188,24."
    },
    {
      "title": "Dida82 passa na disputa mais equilibrada.",
      "text": "Eliminou Jammes Rodriguez por 174,40 a 161,04. A margem de 13,36 foi a menor das oitavas."
    },
    {
      "title": "Camisa Pesada bate à porta do G10.",
      "text": "Depois de eliminar DuduMathias na B10, subiu do 13º para o 11º lugar na Geral. Está a apenas 4,24 pontos do décimo colocado."
    },
    {
      "title": "Lendinhaxx dá o maior salto da rodada.",
      "text": "Subiu quatro posições na classificação geral, passando do 31º para o 27º lugar."
    },
    {
      "title": "O segundo turno também tem disputa.",
      "text": "Tainha lidera com 1.271,22 pontos, mas Avaih F C aparece em segundo, com 1.262,56. A diferença é de 8,66 pontos."
    }
  ],
